begin;
create extension if not exists pgtap with schema extensions;
create temporary table tap_results(result text) on commit drop;
insert into tap_results select plan(4);
insert into auth.users(id,email) values('11111111-ffff-4111-8111-111111111111','lifecycle-host@example.com'),('22222222-ffff-4222-8222-222222222222','lifecycle-player@example.com');
select public.create_party('11111111-ffff-4111-8111-111111111111','33333333-ffff-4333-8333-333333333333',0);
select public.open_party_lobby('11111111-ffff-4111-8111-111111111111',(select id from public.parties limit 1),'44444444-ffff-4444-8444-444444444444',0);
select public.join_party('22222222-ffff-4222-8222-222222222222',(select code from public.parties limit 1),'Ada','55555555-ffff-4555-8555-555555555555',1);
select public.finish_game_session('11111111-ffff-4111-8111-111111111111',(select id from public.parties limit 1),'66666666-ffff-4666-8666-666666666666',2);
insert into tap_results select is((select state from public.game_sessions limit 1),'finished','Host finishes an idle Game session');
select public.adjust_party_score('11111111-ffff-4111-8111-111111111111',(select id from public.parties limit 1),(select id from public.party_members limit 1),'77777777-ffff-4777-8777-777777777777',3,2);
insert into tap_results select is((select score from public.party_members limit 1),2,'signed correction updates Party score');
insert into tap_results select is((select count(*) from public.party_score_adjustments),1::bigint,'correction has an immutable audit row');
select public.create_successor_game_session('11111111-ffff-4111-8111-111111111111',(select id from public.parties limit 1),'88888888-ffff-4888-8888-888888888888',4);
insert into tap_results select is((select state from public.game_sessions where id=(select current_game_session_id from public.parties limit 1)),'lobby','successor starts in an open Lobby');
insert into tap_results select * from finish();
do $$ declare failures text; begin select string_agg(result,E'\n') into failures from tap_results where result like 'not ok%'; if failures is not null then raise exception using message=failures; end if; end $$;
select result from tap_results;
rollback;